package com.aoo.bcg.common.repair;import java.time.*;import java.util.*;import java.util.function.Supplier;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class PostRepairReconciliationTest{@Test void everyDataAndUserPlaneMustMatch(){Map<PostRepairReconciliation.Dimension,Supplier<PostRepairReconciliation.Observation>>probes=new EnumMap<>(PostRepairReconciliation.Dimension.class);for(var d:PostRepairReconciliation.Dimension.values())probes.put(d,()->new PostRepairReconciliation.Observation(true,"same","same","ok"));var report=new PostRepairReconciliation().reconcile("op",probes,Instant.EPOCH);assertTrue(report.passed());probes.put(PostRepairReconciliation.Dimension.UI_READ_MODEL,()->new PostRepairReconciliation.Observation(false,"new","old","cache stale"));assertFalse(new PostRepairReconciliation().reconcile("op",probes,Instant.EPOCH).passed());probes.remove(PostRepairReconciliation.Dimension.BALANCES);assertThrows(IllegalArgumentException.class,()->new PostRepairReconciliation().reconcile("op",probes,Instant.EPOCH));}}
